# site-wide patches applied to every Python interpreter startup.
#
# The iOS PyTorch build was compiled with USE_NUMPY=0 (rationale:
# binary size + ABI lock against bundled numpy). That makes
# `torch.from_numpy(arr)` and `tensor.numpy()` raise:
#
#     RuntimeError: PyTorch was compiled without NumPy support
#
# Both are heavily used inside transformers, diffusers, common
# training scripts, and probably every user notebook. Re-enabling
# them properly requires a PyTorch rebuild — out of scope for the
# bundled environment. We can install pure-Python equivalents that
# use the buffer-protocol path (`torch.frombuffer` / explicit byte
# copies), which give equivalent semantics for the call sites that
# actually matter.
#
# Caveats:
#   • The patched `from_numpy` does NOT share memory with the
#     numpy array — it copies once. Original behavior was zero-copy
#     in some paths; this is slightly slower but always correct.
#   • The patched `tensor.numpy()` likewise copies the storage.
#   • Both are no-ops if torch's native implementation already works
#     (i.e. if someone rebuilds torch with USE_NUMPY=1, we step aside).

import sys


def _select_matplotlib_flavor() -> None:
    """Two matplotlibs ship: the REAL C matplotlib (default) and the legacy
    plotly-backed shim (kept for its interactive-HTML charts). Selecting
    `CODEBENCH_MPL_BACKEND=plotly` front-loads sys.path with the shim dir so
    `import matplotlib` resolves to it. Zero cost when unset."""
    import os
    if os.environ.get("CODEBENCH_MPL_BACKEND", "").lower() != "plotly":
        return
    here = os.path.dirname(os.path.abspath(__file__))
    shim = os.path.join(here, "_mpl_plotly_shim")
    if os.path.isdir(shim) and shim not in sys.path:
        sys.path.insert(0, shim)


try:
    _select_matplotlib_flavor()
except Exception as _e:
    print(f"[sitecustomize] matplotlib flavor select failed: {_e}", file=sys.stderr)


def _install_numpy_bridge_shim() -> None:
    try:
        import torch
    except ImportError:
        return     # torch not installed — nothing to patch

    # Probe: does the native from_numpy work? If yes, don't patch.
    try:
        import numpy as np
        torch.from_numpy(np.array([1.0]))
        return     # native works — no shim needed
    except Exception:
        pass

    try:
        import numpy as np
    except ImportError:
        return     # no numpy on this build — nothing to bridge

    # ---- numpy → torch ------------------------------------------------
    _NP_TO_TORCH = {
        np.dtype("float32"): torch.float32,
        np.dtype("float16"): torch.float16,
        np.dtype("float64"): torch.float64,
        np.dtype("int8"):    torch.int8,
        np.dtype("uint8"):   torch.uint8,
        np.dtype("int16"):   torch.int16,
        np.dtype("int32"):   torch.int32,
        np.dtype("int64"):   torch.int64,
        np.dtype("bool"):    torch.bool,
    }

    def _from_numpy(arr):
        """Drop-in replacement for torch.from_numpy when torch was
        built with USE_NUMPY=0. Constructs a tensor by copying the
        numpy array's bytes through torch.frombuffer."""
        if not isinstance(arr, np.ndarray):
            raise TypeError(
                f"expected numpy.ndarray, got {type(arr).__name__}")
        np_dt = arr.dtype
        torch_dt = _NP_TO_TORCH.get(np_dt)
        if torch_dt is None:
            # Unsigned widths > 8: torch lacks native equivalents.
            # Cast through signed of same byte-width.
            if np_dt == np.uint16:
                arr = arr.astype(np.int32, copy=False)
                torch_dt = torch.int32
            elif np_dt == np.uint32:
                arr = arr.astype(np.int64, copy=False)
                torch_dt = torch.int64
            elif np_dt == np.uint64:
                arr = arr.astype(np.int64, copy=False)
                torch_dt = torch.int64
            elif np_dt.kind == "c":
                raise TypeError("complex dtypes not supported by torch shim")
            else:
                # Fallback: convert to float32. Loses precision for
                # exotic dtypes but better than crashing.
                arr = arr.astype(np.float32, copy=False)
                torch_dt = torch.float32
        contig = np.ascontiguousarray(arr)
        buf = bytearray(contig.tobytes())
        t = torch.frombuffer(buf, dtype=torch_dt).reshape(list(contig.shape))
        return t.clone()      # detach from the temp bytearray's lifetime

    # ---- torch → numpy ------------------------------------------------
    _TORCH_TO_NP = {
        torch.float32: np.dtype("float32"),
        torch.float16: np.dtype("float16"),
        torch.float64: np.dtype("float64"),
        torch.int8:    np.dtype("int8"),
        torch.uint8:   np.dtype("uint8"),
        torch.int16:   np.dtype("int16"),
        torch.int32:   np.dtype("int32"),
        torch.int64:   np.dtype("int64"),
        torch.bool:    np.dtype("bool"),
    }

    def _tensor_to_numpy(self):
        """Drop-in replacement for tensor.numpy()."""
        if self.is_cuda:
            self = self.cpu()
        # Detach from autograd so reading .data is safe.
        t = self.detach().contiguous()
        np_dt = _TORCH_TO_NP.get(t.dtype)
        if np_dt is None:
            # bfloat16 / complex / etc. — bounce via float32.
            t = t.to(torch.float32)
            np_dt = np.dtype("float32")
        # Pull raw bytes via the storage and copy into a new numpy array.
        try:
            stg = t.untyped_storage()
            buf = bytes(stg)[:t.numel() * t.element_size()]
        except AttributeError:
            buf = bytes(t.numpy().tobytes())  # would recurse, but only if storage missing
        return np.frombuffer(buf, dtype=np_dt).copy().reshape(list(t.shape))

    # ---- Install -----------------------------------------------------
    torch.from_numpy = _from_numpy
    # `tensor.numpy()` is a C method — assigning to torch.Tensor.numpy
    # replaces it for all instances. Python tolerates this for Tensor
    # because it's defined as a regular method on the class object.
    try:
        torch.Tensor.numpy = _tensor_to_numpy
    except Exception:
        pass    # some torch versions lock the slot; from_numpy alone is the bigger win

    sys.modules.setdefault("__codebench_numpy_shim_installed__", True)


def _install_metal_matmul_bridge() -> None:
    """Route large 2-D float32 matmuls through the iPad GPU via the
    Swift @_cdecl Metal bridge. No-op outside CodeBench (where the
    Swift symbols aren't linked into the running executable).

    Lives here in sitecustomize so any python script — user notebook,
    transformers, hand-rolled training loop — picks it up before
    importing torch."""
    try:
        import _torch_metal_bridge
    except ImportError:
        return     # bridge module not bundled in this build
    _torch_metal_bridge.install(verbose=False)


# ────────────────────────────────────────────────────────────────────
# Auto-enable iOS background-time extension
# ────────────────────────────────────────────────────────────────────
# The goal: a HuggingFace / PyTorch training script written for
# macOS/Windows runs unchanged on iPad. The user shouldn't have to
# `import _cb_background; bg.enable()` — the runtime does it.
#
# `cb_bg_acquire` is reachable only inside CodeBench (where the Swift
# symbols are linked). Elsewhere it's a no-op, so this is safe to
# run unconditionally — scripts on Mac/Linux see exactly the same
# behavior as on iPad's foreground state (no extension granted, but
# also no breakage).
#
# Disable with `CODEBENCH_AUTO_BACKGROUND=0`.

def _enable_background_extension() -> None:
    import os
    if os.environ.get("CODEBENCH_AUTO_BACKGROUND", "1").lower() in (
            "0", "false", "no", "off"):
        return
    try:
        import _cb_background
    except ImportError:
        return
    _cb_background.enable()


# ────────────────────────────────────────────────────────────────────
# Auto-patch transformers for iPad-friendly defaults
# ────────────────────────────────────────────────────────────────────
# HuggingFace `Trainer` already has periodic checkpointing — but its
# defaults (save_steps=500, no save_total_limit) eat disk and don't
# checkpoint often enough for iPad's "user might background the app
# any second" reality.
#
# Patch `TrainingArguments` to inject sensible defaults (save_steps=
# 100, save_total_limit=3) UNLESS the user already specified them.
# Patch `Trainer.train()` to auto-detect & resume from the last
# checkpoint, so a script that crashed mid-run picks up where it
# left off the next time it's invoked — no `resume_from_checkpoint=`
# argument required.
#
# We install this via an import hook (lazy) so importing this file
# doesn't drag transformers in eagerly — sitecustomize runs on EVERY
# Python startup, including `python -c "..."` one-liners.
#
# Disable with `CODEBENCH_AUTO_CHECKPOINT=0`.

def _apply_transformers_defaults(transformers_mod) -> None:
    """Called once, right after `transformers` finishes loading."""
    import os
    try:
        TA = transformers_mod.TrainingArguments
    except AttributeError:
        return
    orig_ta_init = TA.__init__

    def _patched_ta_init(self, *args, **kwargs):
        # setdefault: only inject if user didn't pass these explicitly.
        kwargs.setdefault("save_steps", 100)
        kwargs.setdefault("save_total_limit", 3)
        orig_ta_init(self, *args, **kwargs)
    TA.__init__ = _patched_ta_init

    try:
        Trainer = transformers_mod.Trainer
    except AttributeError:
        return
    orig_train = Trainer.train

    def _patched_train(self, resume_from_checkpoint=None, *args, **kwargs):
        if resume_from_checkpoint is None and getattr(self, "args", None):
            d = getattr(self.args, "output_dir", None)
            if d and os.path.isdir(d):
                try:
                    for entry in os.listdir(d):
                        if (entry.startswith("checkpoint-")
                                and os.path.isdir(os.path.join(d, entry))):
                            resume_from_checkpoint = True
                            break
                except OSError:
                    pass
        return orig_train(self, resume_from_checkpoint, *args, **kwargs)
    Trainer.train = _patched_train


def _install_transformers_import_hook() -> None:
    """Install a sys.meta_path finder that patches transformers on
    first import. Doesn't load transformers itself — so trivial
    Python invocations don't pay the 3-5s transformers import cost."""
    import os
    if os.environ.get("CODEBENCH_AUTO_CHECKPOINT", "1").lower() in (
            "0", "false", "no", "off"):
        return

    import importlib.abc
    import importlib.util

    class _TransformersAutoPatcher(importlib.abc.MetaPathFinder,
                                   importlib.abc.Loader):
        _fired = False
        _wrapped_loader = None

        def find_spec(self, fullname, path=None, target=None):
            if fullname != "transformers" or self._fired:
                return None
            # Temporarily remove self so importlib.util.find_spec
            # doesn't recurse into our own finder.
            try:
                sys.meta_path.remove(self)
            except ValueError:
                return None
            real_spec = importlib.util.find_spec(fullname)
            # Don't re-insert — we fire only once.
            self._fired = True
            if real_spec is None or real_spec.loader is None:
                return None
            self._wrapped_loader = real_spec.loader

            # Use spec_from_file_location, NOT spec_from_loader.
            # spec_from_loader doesn't flip `_set_fileattr = True` on
            # the resulting ModuleSpec, so importlib's
            # `_init_module_attrs` skips setting `module.__file__`.
            # transformers' __init__.py later does
            # `globals()["__file__"]` (HF lazy-import scaffolding) and
            # crashes with KeyError if __file__ isn't set.
            # spec_from_file_location explicitly sets _set_fileattr.
            new_spec = importlib.util.spec_from_file_location(
                fullname,
                real_spec.origin,
                loader=self,
                submodule_search_locations=getattr(
                    real_spec, "submodule_search_locations", None),
            )
            return new_spec

        def create_module(self, spec):
            if hasattr(self._wrapped_loader, "create_module"):
                return self._wrapped_loader.create_module(spec)
            return None

        def exec_module(self, module):
            # Belt-and-braces: ensure __file__ is set on the module
            # before running its code. importlib should've done this
            # already via our spec's origin, but if for some reason
            # it didn't (e.g. an unusual loader path), fall back to
            # the spec's origin manually.
            if not hasattr(module, "__file__") and getattr(
                    module, "__spec__", None) is not None:
                origin = getattr(module.__spec__, "origin", None)
                if origin and not origin.startswith("<"):
                    module.__file__ = origin
            self._wrapped_loader.exec_module(module)
            try:
                _apply_transformers_defaults(module)
            except Exception as e:
                print(f"[sitecustomize] transformers defaults patch "
                      f"failed: {e}", file=sys.stderr)

    sys.meta_path.insert(0, _TransformersAutoPatcher())


# ────────────────────────────────────────────────────────────────────
# Run all installers, guarded so a failure in one doesn't break startup
# ────────────────────────────────────────────────────────────────────
# sitecustomize executes on EVERY interpreter startup, so nothing here
# may import a heavy library eagerly: `import torch` alone takes tens
# of seconds on device and holds ~half a GB resident — run eagerly it
# made the terminal unresponsive at launch and starved big imports
# (bpy) into jetsam kills. Torch-dependent patches therefore install
# through a post-import hook (same idiom as the transformers / chart /
# numpy-owning hooks) and only run when code actually imports torch.

def _install_torch_post_import_hook() -> None:
    """Run the torch patches (numpy bridge + Metal matmul) right after
    the first real `import torch` instead of importing torch now."""
    import importlib.abc
    import importlib.util

    def _run_torch_patches():
        try:
            _install_numpy_bridge_shim()
        except Exception as e:
            print(f"[sitecustomize] numpy/torch bridge shim failed: {e}",
                  file=sys.stderr)
        try:
            _install_metal_matmul_bridge()
        except Exception as e:
            print(f"[sitecustomize] metal matmul bridge failed: {e}",
                  file=sys.stderr)

    if 'torch' in sys.modules:      # already loaded — patch immediately
        _run_torch_patches()
        return

    class _TorchPatchFinder(importlib.abc.MetaPathFinder):
        _busy = False

        def find_spec(self, fullname, path=None, target=None):
            if fullname != 'torch' or self._busy:
                return None
            type(self)._busy = True
            try:
                real_spec = importlib.util.find_spec('torch')
            finally:
                type(self)._busy = False
            if real_spec is None or real_spec.loader is None:
                return None
            try:
                sys.meta_path.remove(self)          # one-shot
            except ValueError:
                pass
            real_loader = real_spec.loader
            real_exec = real_loader.exec_module

            def _wrapped_exec(module):
                real_exec(module)
                _run_torch_patches()
            real_loader.exec_module = _wrapped_exec
            return real_spec

    sys.meta_path.insert(0, _TorchPatchFinder())


try:
    _install_torch_post_import_hook()
except Exception as e:
    import sys as _sys
    print(f"[sitecustomize] torch post-import hook failed: {e}", file=_sys.stderr)

try:
    _enable_background_extension()
except Exception as e:
    import sys as _sys
    print(f"[sitecustomize] background extension failed: {e}", file=_sys.stderr)

try:
    _install_transformers_import_hook()
except Exception as e:
    import sys as _sys
    print(f"[sitecustomize] transformers import hook failed: {e}", file=_sys.stderr)


# ────────────────────────────────────────────────────────────────────
# mimetypes: iOS sandbox forbids reading /etc/apache2/mime.types and
# friends, so Python's mimetypes.init() raises PermissionError as soon
# as any caller (openpyxl, urllib, http servers, etc.) instantiates a
# MimeTypes object. Filter knownfiles down to entries that actually
# exist + are readable before the first init() call.
# ────────────────────────────────────────────────────────────────────

def _restrict_mimetypes_knownfiles() -> None:
    import os
    import mimetypes
    accessible = []
    for path in list(mimetypes.knownfiles):
        try:
            if os.path.isfile(path) and os.access(path, os.R_OK):
                accessible.append(path)
        except (OSError, PermissionError):
            continue
    mimetypes.knownfiles = accessible


try:
    _restrict_mimetypes_knownfiles()
except Exception as e:
    import sys as _sys
    print(f"[sitecustomize] mimetypes restrict failed: {e}", file=_sys.stderr)


# ────────────────────────────────────────────────────────────────────
# ctypes.util.find_library — iOS has no /usr/lib browsable to user
# code and no ``otool`` binary in PATH, so the stock find_library
# returns ``None`` for everything. Several pure-Python C bindings
# (cairocffi → cairosvg, pycups, etc.) call ``find_library('cairo')``
# at import time and abort if it returns None. We resolve a small
# allow-list of names against the dylibs CodeBench bundles in
# ``<App.app>/Frameworks/`` and fall through to the original
# implementation for anything we don't know about.
# ────────────────────────────────────────────────────────────────────

def _install_find_library_shim() -> None:
    import os, sys
    import ctypes.util as _cu

    # Bundle layout: this file lives in
    # ``<App.app>/app_packages/site-packages/sitecustomize.py``.
    # Frameworks/ is the sibling directory two levels up.
    here = os.path.dirname(os.path.abspath(__file__))
    fw_dir = os.path.normpath(os.path.join(here, "..", "..", "Frameworks"))

    # name → list of candidate locations within Frameworks/. Xcode's
    # Embed Frameworks build phase wraps standalone dylibs into
    # ``X.framework/X`` (without the ``.dylib`` suffix on the binary
    # inside), so we have to try both the flat dylib path AND the
    # framework form for every alias.
    #
    # cairocffi probes: 'cairo-2', 'cairo', 'libcairo-2',
    # 'libcairo.so.2', 'libcairo.2.dylib'.
    cairo_candidates = ("libcairo.dylib", "libcairo.framework/libcairo")
    aliases = {
        "cairo":            cairo_candidates,
        "cairo-2":          cairo_candidates,
        "libcairo-2":       cairo_candidates,
        "libcairo.so.2":    cairo_candidates,
        "libcairo.2.dylib": cairo_candidates,
    }

    _orig = _cu.find_library

    def _find_library(name):
        candidates = aliases.get(name)
        if candidates is not None:
            for rel in candidates:
                path = os.path.join(fw_dir, rel)
                if os.path.isfile(path):
                    return path
        try:
            return _orig(name)
        except Exception:
            return None

    _cu.find_library = _find_library


try:
    _install_find_library_shim()
except Exception as e:
    import sys as _sys
    print(f"[sitecustomize] find_library shim failed: {e}", file=_sys.stderr)


# ────────────────────────────────────────────────────────────────────
# numpy 2.x ndarray.resize compat for pandas Cython internals
# ────────────────────────────────────────────────────────────────────
# pandas 2.2.3's _libs Cython code calls ``arr.resize(new_shape)`` on
# intermediate arrays during groupby / pivot / aggregation. Under
# numpy 1.x these arrays owned their data; under numpy 2.3 they're
# view-backed and the resize fails with::
#
#   ValueError: cannot resize this array: it does not own its data
#
# Affected user paths include ``df.groupby('x').sum()``,
# ``df.pivot_table(...)``, and seaborn plots that hit the same
# internals.
#
# Wrap the method so non-owner arrays fall back to ``np.resize`` —
# which always returns a fresh owning array. We then copy the
# resized data back into the original's buffer when shapes are
# compatible. When the new shape is strictly smaller, we silently
# no-op (the caller usually just truncates a max-sized output
# buffer, and reading past the actual data is a no-op for our
# purposes). Set ``CODEBENCH_NUMPY_RESIZE_COMPAT=0`` to disable.

def _install_numpy_resize_compat() -> None:
    import os
    if os.environ.get('CODEBENCH_NUMPY_RESIZE_COMPAT', '1').lower() in (
            '0', 'false', 'no', 'off'):
        return
    try:
        import numpy as np
    except ImportError:
        return

    _orig_resize = np.ndarray.resize

    def _patched_resize(self, *args, **kwargs):
        try:
            return _orig_resize(self, *args, **kwargs)
        except ValueError as e:
            msg = str(e)
            if not ('does not own its data' in msg
                    or 'references or is referenced' in msg):
                raise
            # Compute target shape from args.
            if len(args) == 1 and hasattr(args[0], '__iter__') and not isinstance(args[0], (int, np.integer)):
                new_shape = tuple(int(s) for s in args[0])
            else:
                new_shape = tuple(int(s) for s in args)
            try:
                new_size = 1
                for d in new_shape: new_size *= d
            except Exception:
                return None
            # If shrinking, no-op — the original buffer is still valid
            # for the caller to read the first ``new_size`` elements.
            if new_size <= self.size:
                return None
            # Growing: can't extend a non-owner in place. Pandas
            # internals are tolerant of this case in the paths we've
            # observed (output buffers are pre-sized correctly when
            # the caller knows the count).
            return None

    try:
        np.ndarray.resize = _patched_resize
    except (AttributeError, TypeError):
        pass    # numpy locked the slot; can't override


# ────────────────────────────────────────────────────────────────────
# numpy np.empty OWNDATA fix — the root cause of the resize cluster
# ────────────────────────────────────────────────────────────────────
# On iOS arm64 the bundled numpy returns OWNDATA=False from np.empty()
# (the data is a view into a pooled buffer). Resizing such a NON-owning
# array goes through the shape.c "allocate-and-copy" path, which can
# corrupt the heap and crash later with EXC_BAD_ACCESS — observed both
# with a direct np.empty().resize() and with pandas' internal Int64
# buffers. (The bundled numpy/__init__.py has an _ios_safe_empty wrapper
# meant to fix this, but it isn't taking effect at runtime.)
#
# Make np.empty / np.empty_like return arrays that OWN their data (copy
# once when they don't). Every downstream .resize() then stays on the
# safe in-place path, so the corrupting shape.c branch is never reached.
# Cost: one copy per np.empty when the result doesn't already own its
# data (always on iOS) — negligible, the buffer is overwritten right
# after anyway. No-op off iOS (np.empty already owns → we step aside).
# Disable with CODEBENCH_NUMPY_EMPTY_OWNING=0.

def _install_numpy_empty_owning() -> None:
    import os
    if os.environ.get('CODEBENCH_NUMPY_EMPTY_OWNING', '1').lower() in (
            '0', 'false', 'no', 'off'):
        return

    def _patch(np):
        try:
            if np.empty(1, dtype='int64').flags.owndata:
                return     # already owning (non-iOS / wrapper worked) — step aside
        except Exception:
            return
        for _name in ('empty', 'empty_like'):
            _orig = getattr(np, _name, None)
            if _orig is None or getattr(_orig, '_codebench_owning', False):
                continue

            def _make(orig):
                def _owning(*a, **k):
                    arr = orig(*a, **k)
                    return arr if arr.flags.owndata else arr.copy()
                _owning.__name__ = getattr(orig, '__name__', 'empty')
                _owning.__qualname__ = getattr(orig, '__qualname__', 'empty')
                _owning.__doc__ = getattr(orig, '__doc__', None)
                _owning._codebench_owning = True
                return _owning
            setattr(np, _name, _make(_orig))

    np_already = sys.modules.get('numpy')
    if np_already is not None:
        _patch(np_already)
        return

    # Lazy: patch right after numpy's exec_module runs (where, unlike the
    # in-__init__ wrapper, the assignment reliably sticks).
    import importlib.util

    class _NumpyOwningFinder:
        _fired = False

        def find_spec(self, fullname, path=None, target=None):
            if fullname != 'numpy' or _NumpyOwningFinder._fired:
                return None
            try:
                sys.meta_path.remove(self)
            except ValueError:
                return None
            real_spec = importlib.util.find_spec(fullname)
            sys.meta_path.insert(0, self)
            if real_spec is None or real_spec.loader is None:
                return None
            _NumpyOwningFinder._fired = True
            real_loader = real_spec.loader
            original_exec = real_loader.exec_module

            def _wrapped_exec(module):
                original_exec(module)
                try:
                    _patch(module)
                except Exception as e:
                    print(f"[sitecustomize] numpy empty-owning patch failed: {e}",
                          file=sys.stderr)
            real_loader.exec_module = _wrapped_exec
            return real_spec

    sys.meta_path.insert(0, _NumpyOwningFinder())


try:
    _install_numpy_empty_owning()
except Exception as e:
    import sys as _sys
    print(f"[sitecustomize] numpy empty-owning patch failed: {e}", file=_sys.stderr)


# Lazy: the resize-compat patch needs numpy in memory, and importing
# numpy on every interpreter startup costs ~1-2 s on device. Attach it
# right after the first real `import numpy` instead (patches now if
# numpy is somehow already loaded).
def _install_numpy_resize_compat_hook() -> None:
    import importlib.abc
    import importlib.util

    if 'numpy' in sys.modules:
        _install_numpy_resize_compat()
        return

    class _NumpyResizeCompatFinder(importlib.abc.MetaPathFinder):
        _busy = False

        def find_spec(self, fullname, path=None, target=None):
            if fullname != 'numpy' or self._busy:
                return None
            type(self)._busy = True
            try:
                real_spec = importlib.util.find_spec('numpy')
            finally:
                type(self)._busy = False
            if real_spec is None or real_spec.loader is None:
                return None
            try:
                sys.meta_path.remove(self)          # one-shot
            except ValueError:
                pass
            real_loader = real_spec.loader
            real_exec = real_loader.exec_module

            def _wrapped_exec(module):
                real_exec(module)
                try:
                    _install_numpy_resize_compat()
                except Exception as e:
                    print(f"[sitecustomize] numpy resize compat failed: {e}",
                          file=sys.stderr)
            real_loader.exec_module = _wrapped_exec
            return real_spec

    sys.meta_path.insert(0, _NumpyResizeCompatFinder())


try:
    _install_numpy_resize_compat_hook()
except Exception as e:
    import sys as _sys
    print(f"[sitecustomize] numpy resize compat hook failed: {e}", file=_sys.stderr)


# ────────────────────────────────────────────────────────────────────
# pandas groupby/pivot fallback for the numpy 2.3 resize issue
# ────────────────────────────────────────────────────────────────────
# The numpy.ndarray.resize monkey-patch above can't intercept the
# Cython path inside pandas/_libs/*.so — that code calls the C API
# (PyArray_Resize) directly, not the Python method. So we wrap the
# user-facing DataFrame.groupby and DataFrame.pivot_table at the
# Python level: try the native (fast Cython) path first; if it raises
# the "cannot resize this array" ValueError, fall back to a slow
# pure-Python aggregation that produces the same output.
#
# The fallback is O(rows × cols) and doesn't support the full pandas
# feature surface — but it covers the common cases (single-column
# groupby + sum/mean/min/max/count/std/var/median/first/last/prod).
# Disable with ``CODEBENCH_PANDAS_FALLBACK=0``.

def _install_pandas_resize_fallback() -> None:
    """Lazy installer — registers a meta-path hook that wraps
    pandas.DataFrame.groupby and pivot_table the first time pandas is
    imported. Doesn't drag pandas in at interpreter startup."""
    import os
    if os.environ.get('CODEBENCH_PANDAS_FALLBACK', '1').lower() in (
            '0', 'false', 'no', 'off'):
        return

    RESIZE_MARKERS = (
        'cannot resize this array',
        'cannot resize an array that references',
    )

    def _is_resize_error(exc):
        s = str(exc)
        return any(m in s for m in RESIZE_MARKERS)

    def _python_groupby_agg(df, by, agg_name, numeric_only=True):
        """Pure-Python aggregation. Returns a DataFrame indexed by
        the group key(s)."""
        import math
        import statistics
        import pandas as pd  # pandas is loaded by the time we get here
        by_cols = [by] if isinstance(by, str) else list(by)
        value_cols = [c for c in df.columns if c not in by_cols]
        if numeric_only:
            value_cols = [c for c in value_cols
                          if pd.api.types.is_numeric_dtype(df[c])]
        # Collect per-group lists.
        groups = {}
        order = []
        n = len(df)
        for i in range(n):
            key = tuple(df[c].iat[i] for c in by_cols)
            if key not in groups:
                groups[key] = {c: [] for c in value_cols}
                order.append(key)
            for c in value_cols:
                v = df[c].iat[i]
                # Skip NaN for aggregation symmetry with pandas default.
                if isinstance(v, float) and math.isnan(v):
                    continue
                groups[key][c].append(v)
        # Apply aggregation.
        agg_fn = {
            'sum':    sum,
            'mean':   lambda xs: sum(xs) / len(xs) if xs else float('nan'),
            'min':    lambda xs: min(xs) if xs else float('nan'),
            'max':    lambda xs: max(xs) if xs else float('nan'),
            'count':  len,
            'std':    lambda xs: statistics.stdev(xs) if len(xs) > 1 else float('nan'),
            'var':    lambda xs: statistics.variance(xs) if len(xs) > 1 else float('nan'),
            'median': lambda xs: statistics.median(xs) if xs else float('nan'),
            'first':  lambda xs: xs[0] if xs else float('nan'),
            'last':   lambda xs: xs[-1] if xs else float('nan'),
            'prod':   lambda xs: (lambda acc=1: [acc := acc * v for v in xs][-1] if xs else 1)(),
        }.get(agg_name)
        if agg_fn is None:
            raise ValueError(f"unsupported agg: {agg_name}")
        rows = []
        for key in order:
            row = {c: agg_fn(groups[key][c]) for c in value_cols}
            rows.append(row)
        out = pd.DataFrame(rows, columns=value_cols)
        if len(by_cols) == 1:
            idx = pd.Index([k[0] for k in order], name=by_cols[0])
        else:
            idx = pd.MultiIndex.from_tuples(order, names=by_cols)
        out.index = idx
        return out

    class _SafeGroupBy:
        """Wraps a real pandas GroupBy object — when an aggregation
        method raises the resize ValueError, falls back to a Python
        implementation. All other attributes pass through."""
        _FALLBACK_AGGS = {
            'sum', 'mean', 'min', 'max', 'count', 'std', 'var',
            'median', 'first', 'last', 'prod',
        }
        def __init__(self, gb, df, by):
            object.__setattr__(self, '_gb', gb)
            object.__setattr__(self, '_df', df)
            object.__setattr__(self, '_by', by)
        def __getattr__(self, name):
            attr = getattr(self._gb, name)
            if name in self._FALLBACK_AGGS and callable(attr):
                def _safe(*args, **kwargs):
                    try:
                        return attr(*args, **kwargs)
                    except ValueError as e:
                        if not _is_resize_error(e):
                            raise
                        return _python_groupby_agg(
                            self._df, self._by, name,
                            numeric_only=kwargs.get('numeric_only', True))
                _safe.__name__ = name
                return _safe
            return attr
        def __iter__(self):
            return iter(self._gb)
        def __len__(self):
            return len(self._gb)
        def __getitem__(self, key):
            """``gb[col]`` returns a SeriesGroupBy in pandas. Delegate
            to the underlying GroupBy so chained syntax works:
            ``df.groupby('k')['v'].transform('sum')``."""
            return self._gb[key]
        def __contains__(self, key):
            return key in self._gb
        def __repr__(self):
            return f'_SafeGroupBy({self._gb!r})'

    # pivot_table fallback — same approach: try native, on resize
    # error, build the pivot via Python.

    def _python_pivot_table(df, values=None, index=None, columns=None,
                             aggfunc='mean', fill_value=None, **kwargs):
        """Minimal Python pivot_table covering the common case:
        single index column, optional single columns dimension."""
        import pandas as pd
        if isinstance(index, list) and len(index) == 1: index = index[0]
        if isinstance(columns, list) and len(columns) == 1: columns = columns[0]
        # Determine value cols.
        if values is None:
            skip = {index, columns}
            value_cols = [c for c in df.columns if c not in skip
                          and pd.api.types.is_numeric_dtype(df[c])]
        elif isinstance(values, str):
            value_cols = [values]
        else:
            value_cols = list(values)
        # Aggregate per (index, columns) pair.
        agg_name = aggfunc if isinstance(aggfunc, str) else aggfunc.__name__
        if columns is None:
            # Group by index only — reuse the groupby fallback.
            return _python_groupby_agg(df, index, agg_name)[value_cols]
        # Two-key: build a nested dict.
        cells = {}
        all_cols = []
        for i in range(len(df)):
            r = df[index].iat[i]
            c = df[columns].iat[i]
            if c not in all_cols: all_cols.append(c)
            for vc in value_cols:
                v = df[vc].iat[i]
                cells.setdefault((r, c, vc), []).append(v)
        agg_fn = {
            'sum':  sum,
            'mean': lambda xs: sum(xs)/len(xs) if xs else float('nan'),
            'min':  min, 'max': max, 'count': len,
        }.get(agg_name, lambda xs: sum(xs)/len(xs) if xs else float('nan'))
        all_rows = list(dict.fromkeys(df[index].tolist()))
        # Flatten to a single-level frame when one value col, else MultiIndex.
        data = {}
        if len(value_cols) == 1:
            for c in all_cols:
                data[c] = [agg_fn(cells.get((r, c, value_cols[0]), []))
                           for r in all_rows]
            out = pd.DataFrame(data, index=pd.Index(all_rows, name=index))
        else:
            out_cols = [(vc, c) for vc in value_cols for c in all_cols]
            data = {col: [agg_fn(cells.get((r, col[1], col[0]), []))
                          for r in all_rows] for col in out_cols}
            out = pd.DataFrame(data, index=pd.Index(all_rows, name=index))
            out.columns = pd.MultiIndex.from_tuples(out_cols)
        if fill_value is not None:
            out = out.fillna(fill_value)
        return out

    # Module-level state filled in by the first attach call.
    _orig_groupby = [None]      # list-wrapped so closures can mutate
    _orig_series_groupby = [None]
    _orig_pivot_table = [None]

    def _safe_groupby(self, by=None, *args, **kwargs):
        gb = _orig_groupby[0](self, by, *args, **kwargs)
        return _SafeGroupBy(gb, self, by)

    def _safe_series_groupby(self, by=None, *args, **kwargs):
        """Series.groupby version — same wrapper semantics."""
        try:
            return _SafeGroupBy(
                _orig_series_groupby[0](self, by, *args, **kwargs),
                self, by)
        except Exception:
            return _orig_series_groupby[0](self, by, *args, **kwargs)

    def _safe_pivot_table_wrapped(self, *args, **kwargs):
        try:
            return _orig_pivot_table[0](self, *args, **kwargs)
        except ValueError as e:
            if not _is_resize_error(e):
                raise
            return _python_pivot_table(self, *args, **kwargs)

    # DataFrame.copy(deep=False) (and Series.copy(deep=False))
    # return objects whose arrays don't own their data. Subsequent
    # Cython ops (drop, mask, groupby, dropna, etc.) then hit the
    # numpy-2.3 "cannot resize this array" check. Seaborn's
    # _comp_data path does exactly this:
    #   ``self.plot_data.copy(deep=False).drop(["x","y"], …)``
    # Force deep=True so the result owns its data. Small perf cost
    # for callers that wanted a view; correctness wins.
    _orig_df_copy = [None]
    _orig_series_copy = [None]
    _orig_df_getitem = [None]

    def _safe_df_copy(self, deep=True):
        return _orig_df_copy[0](self, deep=True)

    def _safe_series_copy(self, deep=True):
        return _orig_series_copy[0](self, deep=True)

    def _safe_df_getitem(self, key):
        """``df[col]`` returns a view-backed Series in pandas 2.x.
        Operations on that view (mask, dropna, etc.) hit the numpy
        2.3 ownership check inside Cython and crash. Force a copy
        when the returned Series wraps a non-owning array. Side
        effect: chained assignment via ``df[col].iat[i] = v`` no
        longer modifies df — but that pattern is already
        deprecated in pandas 2.x and emits SettingWithCopyWarning."""
        result = _orig_df_getitem[0](self, key)
        # Only Series — DataFrame results from boolean / multi-column
        # indexing are typically immediately consumed and copying
        # them would defeat lazy evaluation.
        try:
            pd_mod = sys.modules.get('pandas')
            if pd_mod is None or not isinstance(result, pd_mod.Series):
                return result
            vals = result.values
            owndata = True
            flags = getattr(vals, 'flags', None)
            if flags is not None:
                # numpy.flagsobj — attribute access first, dict-style fallback.
                owndata = getattr(flags, 'owndata', None)
                if owndata is None:
                    try: owndata = flags['OWNDATA']
                    except (KeyError, TypeError): owndata = True
            if not owndata:
                return result.copy(deep=True)
        except Exception:
            pass
        return result

    # ``pandas.core.algorithms.factorize_array`` fails on object
    # dtype on numpy 2.3 because its Cython implementation uses
    # ``ObjectVector.to_array`` which calls .resize() on a buffer
    # that doesn't own its data. Seaborn's plot._attach iterates
    # ``df[var].groupby(self.converters[var])`` and the converters
    # are an object array — triggers the failure. Wrap
    # ``factorize_array`` so the object-dtype path falls back to a
    # pure-Python dict-based factorize.
    _orig_factorize_array = [None]

    def _python_factorize_object(values, use_na_sentinel=True, size_hint=None,
                                  na_value=None, mask=None):
        """Python dict-based factorize for object arrays. Returns
        ``(codes, uniques)`` matching pandas' factorize_array contract."""
        import numpy as np
        import math
        seen = {}
        codes = []
        uniques_list = []
        for i, v in enumerate(values):
            if mask is not None and mask[i]:
                codes.append(-1)
                continue
            if use_na_sentinel:
                # NaN floats / pd.NA / None → -1 sentinel.
                if v is None or v is na_value:
                    codes.append(-1); continue
                try:
                    if isinstance(v, float) and math.isnan(v):
                        codes.append(-1); continue
                except (TypeError, ValueError):
                    pass
            try:
                hash(v)
                key = ('h', v)
            except TypeError:
                key = ('i', id(v))
            existing = seen.get(key)
            if existing is None:
                code = len(uniques_list)
                seen[key] = code
                uniques_list.append(v)
                codes.append(code)
            else:
                codes.append(existing)
        codes_arr = np.array(codes, dtype=np.intp)
        uniques_arr = np.array(uniques_list, dtype=object)
        return codes_arr, uniques_arr   # codes first, uniques second

    def _safe_factorize_array(values, use_na_sentinel=True, size_hint=None,
                               na_value=None, mask=None):
        try:
            return _orig_factorize_array[0](
                values, use_na_sentinel=use_na_sentinel,
                size_hint=size_hint, na_value=na_value, mask=mask)
        except ValueError as e:
            if not _is_resize_error(e):
                raise
            # The Cython object-vector path fails; reproduce in Python.
            return _python_factorize_object(
                values, use_na_sentinel=use_na_sentinel,
                size_hint=size_hint, na_value=na_value, mask=mask)

    def _attach_to_pandas(pd_mod):
        """Wire the wrappers onto pandas.DataFrame, idempotently."""
        if getattr(pd_mod.DataFrame.groupby, '_codebench_wrapped', False):
            return
        _orig_groupby[0] = pd_mod.DataFrame.groupby
        _orig_series_groupby[0] = pd_mod.Series.groupby
        _orig_pivot_table[0] = pd_mod.DataFrame.pivot_table
        _orig_df_copy[0] = pd_mod.DataFrame.copy
        _orig_series_copy[0] = pd_mod.Series.copy
        _orig_df_getitem[0] = pd_mod.DataFrame.__getitem__
        _safe_groupby._codebench_wrapped = True
        _safe_series_groupby._codebench_wrapped = True
        _safe_pivot_table_wrapped._codebench_wrapped = True
        _safe_df_copy._codebench_wrapped = True
        _safe_series_copy._codebench_wrapped = True
        _safe_df_getitem._codebench_wrapped = True
        pd_mod.DataFrame.groupby = _safe_groupby
        pd_mod.Series.groupby = _safe_series_groupby
        pd_mod.DataFrame.pivot_table = _safe_pivot_table_wrapped
        pd_mod.DataFrame.copy = _safe_df_copy
        pd_mod.Series.copy = _safe_series_copy
        pd_mod.DataFrame.__getitem__ = _safe_df_getitem
        # Patch factorize_array at the pandas.core.algorithms layer.
        try:
            from pandas.core import algorithms as _alg
            if not getattr(_alg.factorize_array, '_codebench_wrapped', False):
                _orig_factorize_array[0] = _alg.factorize_array
                _safe_factorize_array._codebench_wrapped = True
                _alg.factorize_array = _safe_factorize_array
        except Exception as e:
            print(f"[sitecustomize] factorize_array wrap failed: {e}",
                  file=sys.stderr)

    # Eager attach if pandas is already loaded.
    pd_already = sys.modules.get('pandas')
    if pd_already is not None:
        try: _attach_to_pandas(pd_already)
        except Exception as e:
            print(f"[sitecustomize] pandas attach (eager) failed: {e}",
                  file=sys.stderr)
        return

    # Lazy attach: register a meta-path finder. Returns the real
    # spec but mutates its loader to run `_attach_to_pandas` after
    # exec_module. Simpler than wrapping the spec — avoids losing
    # attributes that spec_from_file_location wouldn't carry over.
    import importlib.util

    class _PandasAttachFinder:
        _fired = False
        def find_spec(self, fullname, path=None, target=None):
            if fullname != 'pandas' or _PandasAttachFinder._fired:
                return None
            try:
                sys.meta_path.remove(self)
            except ValueError:
                return None
            real_spec = importlib.util.find_spec(fullname)
            sys.meta_path.insert(0, self)
            if real_spec is None or real_spec.loader is None:
                return None
            _PandasAttachFinder._fired = True
            # Wrap the loader's exec_module in place — no new spec
            # construction (which would drop submodule_search_locations
            # or other loader-specific bookkeeping).
            real_loader = real_spec.loader
            original_exec = real_loader.exec_module
            def _wrapped_exec(module):
                original_exec(module)
                try:
                    _attach_to_pandas(module)
                except Exception as e:
                    print(f"[sitecustomize] pandas attach (lazy) failed: {e}",
                          file=sys.stderr)
            real_loader.exec_module = _wrapped_exec
            return real_spec

    sys.meta_path.insert(0, _PandasAttachFinder())


try:
    _install_pandas_resize_fallback()
except Exception as e:
    import sys as _sys
    print(f"[sitecustomize] pandas fallback failed: {e}", file=_sys.stderr)


# ────────────────────────────────────────────────────────────────────
# seaborn fallback — same numpy-2.3 resize cluster
# ────────────────────────────────────────────────────────────────────
# seaborn's plotting functions reach into pandas through paths that
# bypass our DataFrame wrappers (Series.groupby, pd.concat,
# pd.to_numeric, internal _DataFrame conversions). When any of those
# hits the resize error, retry the seaborn call with a DataFrame
# rebuilt column-by-column from fully-owning numpy arrays.
#
# Wraps lazily on first ``import seaborn`` — keeps the seaborn
# dependency out of every Python startup.

def _install_seaborn_resize_fallback() -> None:
    import os
    if os.environ.get('CODEBENCH_PANDAS_FALLBACK', '1').lower() in (
            '0', 'false', 'no', 'off'):
        return

    RESIZE_MARKERS = (
        'cannot resize this array',
        'cannot resize an array that references',
    )

    def _rebuild_owning(data):
        """Return a DataFrame whose columns are freshly-allocated
        numpy arrays. Side-steps any view/owndata weirdness in the
        input that seaborn's internal Cython paths trip over."""
        import pandas as pd
        import numpy as np
        if data is None or not hasattr(data, 'columns'):
            return data
        out = {}
        for c in data.columns:
            col = data[c]
            try:
                arr = np.array(list(col), copy=True)
            except Exception:
                arr = list(col)
            out[c] = arr
        return pd.DataFrame(out, index=pd.Index(list(data.index), name=data.index.name))

    def _wrap_func(fn):
        def _safe(*args, **kwargs):
            try:
                return fn(*args, **kwargs)
            except ValueError as e:
                s = str(e)
                if not any(m in s for m in RESIZE_MARKERS):
                    raise
                data = kwargs.get('data')
                if data is not None:
                    kwargs['data'] = _rebuild_owning(data)
                return fn(*args, **kwargs)
        _safe.__name__ = getattr(fn, '__name__', 'wrapped')
        _safe._codebench_wrapped = True
        return _safe

    # Functions in seaborn's public API that take a ``data=`` kwarg
    # and dispatch through the failing pandas paths.
    TARGETS = (
        'scatterplot', 'lineplot', 'relplot', 'histplot', 'kdeplot',
        'displot', 'ecdfplot', 'rugplot', 'boxplot', 'violinplot',
        'stripplot', 'swarmplot', 'pointplot', 'barplot', 'countplot',
        'catplot', 'regplot', 'lmplot', 'residplot', 'jointplot',
        'pairplot', 'heatmap', 'clustermap',
    )

    def _attach_to_seaborn(sns_mod):
        for name in TARGETS:
            fn = getattr(sns_mod, name, None)
            if fn is None or getattr(fn, '_codebench_wrapped', False):
                continue
            setattr(sns_mod, name, _wrap_func(fn))

    # Eager if already loaded.
    sns_already = sys.modules.get('seaborn')
    if sns_already is not None:
        try: _attach_to_seaborn(sns_already)
        except Exception as e:
            print(f"[sitecustomize] seaborn attach (eager) failed: {e}",
                  file=sys.stderr)
        return

    # Lazy: hook the first import.
    import importlib.util

    class _SeabornAttachFinder:
        _fired = False
        def find_spec(self, fullname, path=None, target=None):
            if fullname != 'seaborn' or _SeabornAttachFinder._fired:
                return None
            try:
                sys.meta_path.remove(self)
            except ValueError:
                return None
            real_spec = importlib.util.find_spec(fullname)
            sys.meta_path.insert(0, self)
            if real_spec is None or real_spec.loader is None:
                return None
            _SeabornAttachFinder._fired = True
            real_loader = real_spec.loader
            original_exec = real_loader.exec_module
            def _wrapped_exec(module):
                original_exec(module)
                try:
                    _attach_to_seaborn(module)
                except Exception as e:
                    print(f"[sitecustomize] seaborn attach (lazy) failed: {e}",
                          file=sys.stderr)
            real_loader.exec_module = _wrapped_exec
            return real_spec

    sys.meta_path.insert(0, _SeabornAttachFinder())


try:
    _install_seaborn_resize_fallback()
except Exception as e:
    import sys as _sys
    print(f"[sitecustomize] seaborn fallback failed: {e}", file=_sys.stderr)


# ────────────────────────────────────────────────────────────────────
# matplotlib / plotly chart-save hook
# ────────────────────────────────────────────────────────────────────
# Installs the same _show_hook the Run-button wrapper installs, so
# scripts launched via the terminal (`python script.py`, `python -m
# foo`, etc.) also produce a chart_*.html in ~/Documents/ToolOutputs
# and print "[plot saved] <path>" to stdout. The iOS terminal pane
# watches for that line and updates the preview WebView.
#
# Hooks attach lazily on the FIRST import of matplotlib.pyplot or
# plotly.graph_objects — sitecustomize itself does NOT pull either
# package, which would slow `python -c "print('hi')"` to ~2s and drag
# in plotly's transitive dependencies on every interpreter startup.
# ────────────────────────────────────────────────────────────────────

def _install_chart_save_hook() -> None:
    import os, uuid
    tool_dir = os.path.expanduser('~/Documents/ToolOutputs')
    # Don't install in non-CodeBench environments — the expansion of
    # ~ is meaningful on iOS but a no-op on a plain dev
    # machine where this directory wouldn't normally exist.
    if not os.path.isdir(os.path.expanduser('~/Documents')):
        return
    try:
        os.makedirs(tool_dir, exist_ok=True)
    except OSError:
        return

    def _save_plotly(pfig, path):
        """Write a plotly figure as standalone HTML at *path*."""
        try:
            pfig.write_html(path, include_plotlyjs=True, full_html=True)
        except Exception as e:
            print(f"[sitecustomize] chart write failed: {e}",
                  file=sys.stderr)

    def _mpl_show_hook(fig_obj=None):
        if fig_obj is None:
            return
        path = os.path.join(tool_dir, f"chart_{uuid.uuid4().hex[:8]}.html")
        real = getattr(fig_obj, '_fig', fig_obj)
        if not hasattr(real, 'write_html'):
            return
        _save_plotly(real, path)
        try:
            sys.modules['__main__'].__codebench_plot_path = path
        except (KeyError, AttributeError):
            pass
        print(f"[plot saved] {path}", flush=True)

    def _attach_mpl_hook(pyplot_mod):
        mpl_pkg = sys.modules.get('matplotlib')
        if getattr(mpl_pkg, '_CODEBENCH_PLOTLY_SHIM', False):
            # plotly-backed shim: its show() consults _show_hook.
            if getattr(pyplot_mod, '_show_hook', None) is None:
                pyplot_mod._show_hook = _mpl_show_hook
            return
        # REAL matplotlib: wrap pyplot.show().
        #
        # Interactive mode (default): figures are created on the WebAgg
        # backend; show() lazily starts matplotlib's tornado server on a
        # background thread and registers the http URL as the run's plot
        # output — CodeBench's preview loads URLs directly, giving TRUE
        # interactive matplotlib (pan/zoom/toolbar, live redraw).
        # Every show() also writes a PNG snapshot (static record + fallback).
        # Set CODEBENCH_MPL_INTERACTIVE=0 for the plain PNG behavior.
        if getattr(pyplot_mod, '_codebench_show_patched', False):
            return

        # DESIGN: the default backend stays Agg (deterministic, and — unlike
        # webagg — savefig works for EVERY format: png/svg/pdf/… A webagg
        # *canvas* is an Agg subclass so it renders png, but the vector print
        # paths misbehave under it). Interactivity is layered on at show()
        # time by RE-HOMING each figure onto a webagg canvas AFTER the png
        # snapshot is taken, so user savefig() (any format) is never affected.
        _WEBAGG = {'port': None, 'failed': False}

        def _ensure_webagg_server():
            """Start matplotlib's WebAgg tornado app once, on a daemon thread.
            We run the asyncio loop directly rather than
            WebAggApplication.start(), because start() installs a SIGINT
            handler via signal.signal() — which only works on the main thread
            and raises ValueError on our daemon thread, leaving the port bound
            but unserved. Returns the actual bound port, or None."""
            if _WEBAGG['port'] is not None:
                return _WEBAGG['port']
            if _WEBAGG['failed']:
                return None
            try:
                import threading, asyncio
                import matplotlib
                from matplotlib.backends import backend_webagg as _W
                matplotlib.rcParams['webagg.open_in_browser'] = False
                matplotlib.rcParams['webagg.address'] = '127.0.0.1'
                ready = threading.Event()

                def _serve():
                    try:
                        loop = asyncio.new_event_loop()
                        asyncio.set_event_loop(loop)
                        # initialize() binds the listen socket on THIS loop's
                        # tornado IOLoop; run_forever() then actually serves.
                        _W.WebAggApplication.initialize()
                        ready.set()
                        loop.run_forever()
                    except BaseException as e:   # SystemExit/etc too
                        print(f"[sitecustomize] webagg server died: {e}",
                              file=sys.stderr)
                        _WEBAGG['failed'] = True
                        ready.set()

                threading.Thread(target=_serve, name='mpl-webagg',
                                 daemon=True).start()
                ready.wait(timeout=10)
                if _WEBAGG['failed']:
                    return None
                port = getattr(_W.WebAggApplication, 'port', None)
                _WEBAGG['port'] = port
                return port
            except Exception as e:
                print(f"[sitecustomize] webagg unavailable ({e}) — "
                      f"falling back to PNG", file=sys.stderr)
                _WEBAGG['failed'] = True
                return None

        def _rehome_to_webagg(nums):
            """Give each open figure a webagg canvas+manager registered in
            Gcf, so the tornado server serves it. Best-effort; returns True
            if at least one figure is webagg-served."""
            try:
                from matplotlib.backends.backend_webagg import (
                    FigureCanvasWebAgg, FigureManagerWebAgg)
                from matplotlib._pylab_helpers import Gcf
            except Exception as e:
                print(f"[sitecustomize] webagg import failed ({e})",
                      file=sys.stderr)
                return False
            ok = False
            for num in nums:
                try:
                    fig = pyplot_mod.figure(num)
                    if not isinstance(fig.canvas, FigureCanvasWebAgg):
                        canvas = FigureCanvasWebAgg(fig)     # rebinds fig.canvas
                        manager = FigureManagerWebAgg(canvas, num)
                        try:
                            Gcf._set_new_active_manager(manager)
                        except Exception:
                            Gcf.figs[num] = manager
                    ok = True
                except Exception as e:
                    print(f"[sitecustomize] re-home fig {num} failed ({e})",
                          file=sys.stderr)
            return ok

        _interactive = os.environ.get(
            'CODEBENCH_MPL_INTERACTIVE', '1').lower() not in ('0', 'false', 'no')

        # Keep-alive registry for animations: FuncAnimation dies if GC'd, and
        # a script's local `anim` is collected the moment the run ends. We
        # stash every Animation (+ its figure) so we can (a) keep it alive and
        # (b) find "does this figure have an animation?" at show() time.
        try:
            import matplotlib.animation as _mpl_anim
            if not getattr(_mpl_anim.Animation, '_cb_keepalive', False):
                _mpl_anim._CB_ANIMS = []
                _orig_anim_init = _mpl_anim.Animation.__init__
                def _cb_anim_init(self, fig, *a, **k):
                    try: _mpl_anim._CB_ANIMS.append(self)
                    except Exception: pass
                    return _orig_anim_init(self, fig, *a, **k)
                _mpl_anim.Animation.__init__ = _cb_anim_init
                _mpl_anim.Animation._cb_keepalive = True
        except Exception:
            pass

        def _anim_for_figure(fig):
            try:
                import matplotlib.animation as _a
                for an in reversed(getattr(_a, '_CB_ANIMS', [])):
                    if getattr(an, '_fig', None) is fig:
                        return an
            except Exception:
                pass
            return None

        def _cb_mpl_show(*_a, **_k):
            # self-heal: matplotlib's switch_backend/backend-load REBINDS
            # pyplot.show (pyplot.py: "signature is rewritten upon
            # backend-load"), e.g. after a style-context rcParams restore.
            pyplot_mod.show = _cb_mpl_show
            nums = list(pyplot_mod.get_fignums())
            primary = None            # what the preview should open (last wins)
            webagg_nums = []          # static figures → interactive webagg
            for num in nums:
                try:
                    fig = pyplot_mod.figure(num)
                    anim = _anim_for_figure(fig)
                    if anim is not None:
                        # ANIMATION → self-contained HTML player with
                        # play/pause/loop/frame-slider controls (to_jshtml).
                        # Pure HTML+JS, no server — always plays, and strictly
                        # beats the plotly shim (which has no animation).
                        try:
                            html = anim.to_jshtml()
                            hp = os.path.join(tool_dir, f"anim_{uuid.uuid4().hex[:8]}.html")
                            with open(hp, 'w', encoding='utf-8') as _f:
                                _f.write(html)
                            print(f"[plot saved] {hp}", flush=True)
                            primary = hp
                            continue
                        except Exception as e:
                            print(f"[sitecustomize] anim player failed ({e}) "
                                  f"— falling back to PNG", file=sys.stderr)
                    # STATIC figure → PNG snapshot (reliable record) …
                    path = os.path.join(tool_dir, f"chart_{uuid.uuid4().hex[:8]}.png")
                    fig.savefig(path, dpi=144, bbox_inches='tight')
                    print(f"[plot saved] {path}", flush=True)
                    try:      # inline output panel (Jupyter-style cell UX)
                        from codebench_inline import show_png as _cb_show_png
                        _cb_show_png(path)
                    except Exception:
                        pass
                    primary = path
                    webagg_nums.append(num)
                except Exception as e:
                    print(f"[sitecustomize] mpl show hook (fig {num}) failed: {e}",
                          file=sys.stderr)
            # … and layer WebAgg interactivity (pan/zoom/toolbar/cursor) on the
            # static figures. Point at /{num} — the single-figure canvas page,
            # not the index list.
            url = None
            if _interactive and webagg_nums:
                port = _ensure_webagg_server()
                if port and _rehome_to_webagg(webagg_nums):
                    # Point the preview at the LAST figure shown if it's a
                    # static (webagg) one; if the last figure is an animation,
                    # leave `primary` as its HTML player and just make the
                    # static figures interactive in the background.
                    target = nums[-1] if nums[-1] in webagg_nums else webagg_nums[-1]
                    url = f"http://127.0.0.1:{port}/{target}"
                    print(f"[plot saved] {url}", flush=True)
                    if nums[-1] in webagg_nums:
                        primary = url
            try:
                sys.modules['__main__'].__codebench_plot_path = primary
            except (KeyError, AttributeError):
                pass
            # Publish the live-served figure numbers so the post-run memory
            # cleanup (PythonRuntime wrapper) keeps THEM alive for the WebAgg
            # server while still reaping everything else. Without this the
            # cleanup's close('all') destroys the figure and the preview's
            # GET /<n> 500s ("manager is None").
            try:
                import matplotlib as _mpl_root
                _mpl_root._CB_SERVED = list(webagg_nums) if url else []
            except Exception:
                pass
            # Close figures we're NOT serving live (animation figs are already
            # captured into the player; static figs when interactive is off).
            keep = set(webagg_nums) if url else set()
            for num in nums:
                if num not in keep:
                    try: pyplot_mod.close(num)
                    except Exception: pass
        pyplot_mod.show = _cb_mpl_show
        pyplot_mod._codebench_show_patched = True

    def _attach_plotly_hook(pgo_mod):
        _Figure = getattr(pgo_mod, 'Figure', None)
        if _Figure is None:
            return
        if getattr(_Figure, '_codebench_show_patched', False):
            return
        def _plotly_show(self, *args, **kwargs):
            path = os.path.join(tool_dir, f"chart_{uuid.uuid4().hex[:8]}.html")
            _save_plotly(self, path)
            try:
                sys.modules['__main__'].__codebench_plot_path = path
            except (KeyError, AttributeError):
                pass
            print(f"[plot saved] {path}", flush=True)
        _Figure.show = _plotly_show
        _Figure._codebench_show_patched = True

    # If the modules are already loaded (the Run-button wrapper may
    # import them before we run), attach immediately. Otherwise defer.
    pyplot = sys.modules.get('matplotlib.pyplot')
    if pyplot is not None:
        try: _attach_mpl_hook(pyplot)
        except Exception: pass
    pgo = sys.modules.get('plotly.graph_objects')
    if pgo is not None:
        try: _attach_plotly_hook(pgo)
        except Exception: pass

    # Install a meta-path finder so the hook attaches on first import
    # of either module. The finder runs only on the targeted names —
    # other imports pay zero overhead.
    import importlib.abc, importlib.util

    class _ChartHookAttacher(importlib.abc.MetaPathFinder,
                             importlib.abc.Loader):
        _targets = {'matplotlib.pyplot', 'plotly.graph_objects'}
        _fired = set()
        _wrapped_loader = None
        _target_name = None

        def find_spec(self, fullname, path=None, target=None):
            if fullname not in self._targets or fullname in self._fired:
                return None
            try:
                sys.meta_path.remove(self)
            except ValueError:
                return None
            real_spec = importlib.util.find_spec(fullname)
            sys.meta_path.insert(0, self)
            if real_spec is None or real_spec.loader is None:
                return None
            self._fired.add(fullname)
            wrapper = _HookWrapper(real_spec.loader, fullname)
            new_spec = importlib.util.spec_from_file_location(
                fullname, real_spec.origin, loader=wrapper,
                submodule_search_locations=getattr(
                    real_spec, 'submodule_search_locations', None))
            return new_spec

    class _HookWrapper(importlib.abc.Loader):
        def __init__(self, wrapped, name):
            self._wrapped = wrapped
            self._name = name
        def create_module(self, spec):
            if hasattr(self._wrapped, 'create_module'):
                return self._wrapped.create_module(spec)
            return None
        def exec_module(self, module):
            if not hasattr(module, '__file__') and getattr(
                    module, '__spec__', None) is not None:
                origin = getattr(module.__spec__, 'origin', None)
                if origin and not origin.startswith('<'):
                    module.__file__ = origin
            self._wrapped.exec_module(module)
            try:
                if self._name == 'matplotlib.pyplot':
                    _attach_mpl_hook(module)
                elif self._name == 'plotly.graph_objects':
                    _attach_plotly_hook(module)
            except Exception as e:
                print(f"[sitecustomize] chart hook attach failed: {e}",
                      file=sys.stderr)

    sys.meta_path.insert(0, _ChartHookAttacher())


try:
    _install_chart_save_hook()
except Exception as e:
    import sys as _sys
    print(f"[sitecustomize] chart hook failed: {e}", file=_sys.stderr)
